// LEGACY : gère seulement « mots séparés par un espace ». Il échoue dès qu'il y a
// de la ponctuation, des espaces multiples ou des bords à nettoyer.
// Les tests de caractérisation ci-dessous capturent le comportement ATTENDU.
// Refactore cette fonction pour TOUS les faire passer, sans casser les cas verts.
//   Cible : "Hello, World!" -> "hello-world" ; "  Trim  Me  " -> "trim-me".
export function slugify(title) {
  return String(title).toLowerCase().split(' ').join('-');
}
